import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import React, { useState } from 'react';

interface FilterProps {
  onFilterChange: (filters: { startDate: string; endDate: string; category: string }) => void;
  categories: string[];
}

export const GlassmorphicTransactionFilter: React.FC<FilterProps> = ({ onFilterChange, categories }) => {
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [category, setCategory] = useState('ALL');

  const handleApply = (newStart: string, newEnd: string, newCat: string) => {
    onFilterChange({ startDate: newStart, endDate: newEnd, category: newCat });
  };

  return (
    <div className="backdrop-blur-md bg-white/10 dark:bg-slate-900/40 border border-white/20 dark:border-slate-700/50 rounded-2xl p-6 shadow-xl flex flex-wrap gap-4 items-center justify-between text-slate-800 dark:text-slate-100">
      <div className="flex flex-col gap-1">
        <label className="text-xs font-medium uppercase tracking-wider text-slate-500 dark:text-slate-400">Start Date</label>
        <input 
          type="date"
          value={startDate}
          onChange={(e) => { setStartDate(e.target.value); handleApply(e.target.value, endDate, category); }}
          className="bg-white/5 dark:bg-slate-800/50 border border-white/10 dark:border-slate-700 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
        />
      </div>
      <div className="flex flex-col gap-1">
        <label className="text-xs font-medium uppercase tracking-wider text-slate-500 dark:text-slate-400">End Date</label>
        <input 
          type="date"
          value={endDate}
          onChange={(e) => { setEndDate(e.target.value); handleApply(startDate, e.target.value, category); }}
          className="bg-white/5 dark:bg-slate-800/50 border border-white/10 dark:border-slate-700 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
        />
      </div>
      <div className="flex flex-col gap-1 flex-1 min-w-[200px]">
        <label className="text-xs font-medium uppercase tracking-wider text-slate-500 dark:text-slate-400">Category</label>
        <select
          value={category}
          onChange={(e) => { setCategory(e.target.value); handleApply(startDate, endDate, e.target.value); }}
          className="bg-white/5 dark:bg-slate-800/50 border border-white/10 dark:border-slate-700 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-500"
        >
          <option value="ALL" className="bg-slate-900">All Categories</option>
          {categories.map((cat) => (
            <option key={cat} value={cat} className="bg-slate-900">{cat}</option>
          ))}
        </select>
      </div>
    </div>
  );
};

import React from 'react';

interface BudgetProgressProps {
  category: string;
  spent: number;
  budget: number;
}

export const TailwindAnimatedProgressBar: React.FC<BudgetProgressProps> = ({ category, spent, budget }) => {
  const percentage = Math.min(Math.round((spent / budget) * 100), 100);
  const isOverBudget = spent > budget;

  return (
    <div className="backdrop-blur-md bg-white/10 dark:bg-slate-900/40 border border-white/20 dark:border-slate-700/50 rounded-xl p-4 shadow-lg">
      <div className="flex justify-between items-center mb-2">
        <span className="font-semibold text-slate-800 dark:text-slate-100">{category}</span>
        <span className={`text-sm font-bold ${isOverBudget ? 'text-rose-500' : 'text-slate-600 dark:text-slate-300'}`}>
          ${spent.toFixed(2)} / ${budget.toFixed(2)} ({percentage}%)
        </span>
      </div>
      <div className="w-full bg-slate-200 dark:bg-slate-800 rounded-full h-3 overflow-hidden p-0.5 border border-white/10">
        <div 
          className={`h-full rounded-full transition-all duration-700 ease-out ${
            isOverBudget 
              ? 'bg-gradient-to-r from-rose-500 to-red-600 animate-pulse' 
              : percentage > 80 
              ? 'bg-gradient-to-r from-amber-400 to-orange-500'
              : 'bg-gradient-to-r from-indigo-500 to-emerald-400'
          }`}
          style={{ width: `${percentage}%` }}
        />
      </div>
    </div>
  );
};
